{
  "name": "opencode-hippo-memory",
  "version": "0.4.0",
  "description": "Hippocampus-inspired long-term memory for opencode: 4 memory tools, per-turn digest injection, compaction carry-over and a usage discipline. Powered by hippo-memory-core.",
  "type": "module",
  "main": "lib/index.js",
  "exports": {
    ".": {
      "default": "./lib/index.js"
    },
    "./package.json": "./package.json"
  },
  "files": [
    "lib",
    "README.md",
    "CHANGELOG.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "memory",
    "long-term-memory",
    "hippocampus",
    "agent",
    "llm",
    "deepseek",
    "bun"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/guoxing2024/hippo-memory.git",
    "directory": "packages/opencode-hippo-memory"
  },
  "homepage": "https://github.com/guoxing2024/hippo-memory#readme",
  "engines": {
    "bun": ">=1.1"
  },
  "scripts": {
    "test": "node --test \"test/**/*.test.mjs\""
  },
  "dependencies": {
    "hippo-memory-core": "^0.3.2"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.0.24"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  }
}
